package com.hrms.shift.service;

import com.hrms.assignment.model.AssignmentStatus;import com.hrms.assignment.repository.AssignmentRepository;import com.hrms.audit.service.AuditService;import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.exceptions.*;import com.hrms.shift.dto.*;import com.hrms.shift.model.*;import com.hrms.shift.repository.*;import org.bson.types.ObjectId;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.DayOfWeek;import java.util.*;

@Service public class ShiftService {
 private final ShiftRepository shifts;private final AssignmentRepository assignments;private final AuditService audit;public ShiftService(ShiftRepository s,AssignmentRepository a,AuditService audit){shifts=s;assignments=a;this.audit=audit;}
 @Transactional public ShiftResponse create(CreateShiftRequest r,AuthPrincipal actor){if(shifts.existsByShiftCode(r.shiftCode().strip().toUpperCase()))throw new ConflictException("Shift code already exists");validate(r.startTime(),r.endTime(),r.workingDays(),r.gracePeriodMinutes(),r.earlyDepartureGraceMinutes(),r.expectedBreakMinutes(),r.minimumBreakMinutes());Shift s=new Shift();s.setId(new ObjectId().toHexString());apply(s,r);s.setShiftCode(r.shiftCode().strip().toUpperCase());s.setStatus(ShiftStatus.ACTIVE);s.setCreatedBy(actor.userId());s.setUpdatedBy(actor.userId());shifts.save(s);audit.record(actor,"SHIFT_CREATED","SHIFT",s.getId(),Map.of(),Map.of("shiftCode",s.getShiftCode()),null);return ShiftResponse.from(s);}
 public ShiftPageResponse list(ShiftSearch q){page(q.page(),q.limit());return ShiftPageResponse.from(shifts.search(q),q.limit());}public ShiftResponse get(String id){return ShiftResponse.from(find(id));}
 @Transactional public ShiftResponse update(String id,UpdateShiftRequest r,AuthPrincipal actor){Shift s=find(id);if(r.shiftCode()!=null&&!r.shiftCode().strip().equalsIgnoreCase(s.getShiftCode())&&shifts.existsByShiftCode(r.shiftCode().strip().toUpperCase()))throw new ConflictException("Shift code already exists");LocalTimeHolder t=new LocalTimeHolder(r.startTime()==null?s.getStartTime():r.startTime(),r.endTime()==null?s.getEndTime():r.endTime());Set<DayOfWeek> days=r.workingDays()==null?s.getWorkingDays():r.workingDays();validate(t.start,t.end,days,r.gracePeriodMinutes()==null?s.getGracePeriodMinutes():r.gracePeriodMinutes(),r.earlyDepartureGraceMinutes()==null?s.getEarlyDepartureGraceMinutes():r.earlyDepartureGraceMinutes(),r.expectedBreakMinutes()==null?s.getExpectedBreakMinutes():r.expectedBreakMinutes(),r.minimumBreakMinutes()==null?s.getMinimumBreakMinutes():r.minimumBreakMinutes());if(r.shiftCode()!=null)s.setShiftCode(r.shiftCode().strip().toUpperCase());if(r.name()!=null)s.setName(r.name().strip());if(r.description()!=null)s.setDescription(r.description().strip());if(r.startTime()!=null)s.setStartTime(r.startTime());if(r.endTime()!=null)s.setEndTime(r.endTime());if(r.workingDays()!=null)s.setWorkingDays(EnumSet.copyOf(r.workingDays()));if(r.gracePeriodMinutes()!=null)s.setGracePeriodMinutes(r.gracePeriodMinutes());if(r.earlyDepartureGraceMinutes()!=null)s.setEarlyDepartureGraceMinutes(r.earlyDepartureGraceMinutes());if(r.expectedBreakMinutes()!=null)s.setExpectedBreakMinutes(r.expectedBreakMinutes());if(r.minimumBreakMinutes()!=null)s.setMinimumBreakMinutes(r.minimumBreakMinutes());if(r.flexible()!=null)s.setFlexible(r.flexible());s.setUpdatedBy(actor.userId());shifts.save(s);audit.record(actor,"SHIFT_UPDATED","SHIFT",id,Map.of(),Map.of("shiftCode",s.getShiftCode()),null);return ShiftResponse.from(s);}
 @Transactional public ShiftResponse deactivate(String id,AuthPrincipal actor){Shift s=find(id);if(s.getStatus()==ShiftStatus.INACTIVE)return ShiftResponse.from(s);if(assignments.existsByShiftIdAndStatus(id,AssignmentStatus.ACTIVE))throw new ConflictException("End active employee assignments before deactivating this shift");s.setStatus(ShiftStatus.INACTIVE);s.setUpdatedBy(actor.userId());shifts.save(s);audit.record(actor,"SHIFT_DEACTIVATED","SHIFT",id,Map.of("status","ACTIVE"),Map.of("status","INACTIVE"),null);return ShiftResponse.from(s);}
 @Transactional public ShiftResponse reactivate(String id,AuthPrincipal actor){Shift s=find(id);if(s.getStatus()==ShiftStatus.ACTIVE)return ShiftResponse.from(s);s.setStatus(ShiftStatus.ACTIVE);s.setUpdatedBy(actor.userId());shifts.save(s);audit.record(actor,"SHIFT_REACTIVATED","SHIFT",id,Map.of("status","INACTIVE"),Map.of("status","ACTIVE"),null);return ShiftResponse.from(s);}
 public void validateActive(String id){Shift s=find(id);if(s.getStatus()!=ShiftStatus.ACTIVE)throw new ConflictException("Shift is inactive");}
 private Shift find(String id){if(!ObjectId.isValid(id))throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"Shift id is invalid");return shifts.findById(id).orElseThrow(()->new ResourceNotFoundException("Shift was not found"));}
 private static void validate(java.time.LocalTime start,java.time.LocalTime end,Set<DayOfWeek> days,int grace,int early,int breakM,Integer min){if(start==null||end==null||days==null||days.isEmpty()||grace<0||early<0||breakM<0||(min!=null&&min<0)|| (min!=null&&min>breakM))throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"Shift times, working days, grace and break settings are invalid");}
 private static void apply(Shift s,CreateShiftRequest r){s.setName(r.name().strip());s.setDescription(r.description()==null?null:r.description().strip());s.setStartTime(r.startTime());s.setEndTime(r.endTime());s.setWorkingDays(EnumSet.copyOf(r.workingDays()));s.setGracePeriodMinutes(r.gracePeriodMinutes());s.setEarlyDepartureGraceMinutes(r.earlyDepartureGraceMinutes());s.setExpectedBreakMinutes(r.expectedBreakMinutes());s.setMinimumBreakMinutes(r.minimumBreakMinutes());s.setFlexible(r.flexible());}private record LocalTimeHolder(java.time.LocalTime start,java.time.LocalTime end){}private static void page(int p,int l){if(p<0||l<1||l>100)throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"Page must be non-negative and limit must be between 1 and 100");}
}
